/** Events */
export const events = {
	agentsChanged: makeEvent<AgentsChanged>("agents-changed"),
	analyticsChanged: makeEvent<AnalyticsChanged>("analytics-changed"),
	applicationsChanged: makeEvent<ApplicationsChanged>("applications-changed"),
	browserChanged: makeEvent<BrowserChanged>("browser-changed"),
	chatEvent: makeEvent<ChatEvent>("chat-event"),
	connectorsChanged: makeEvent<ConnectorsChanged>("connectors-changed"),
	conversationsChanged: makeEvent<ConversationsChanged>("conversations-changed"),
	mcpChanged: makeEvent<McpChanged>("mcp-changed"),
	notificationsChanged: makeEvent<NotificationsChanged>("notifications-changed"),
	portfolioChanged: makeEvent<PortfolioChanged>("portfolio-changed"),
	profileChanged: makeEvent<ProfileChanged>("profile-changed"),
	providersChanged: makeEvent<ProvidersChanged>("providers-changed"),
	taskRunChanged: makeEvent<TaskRunChanged>("task-run-changed"),
	tasksChanged: makeEvent<TasksChanged>("tasks-changed"),
};

/* Types */
/**  What an activity entry records. */
export type ActivityKind = 
/**  A tool on one of the user's MCP servers. */
"mcp" | 
/**  A web search by the model's provider (`arguments` holds the query). */
"web_search" | 
/**
 *  A web page the model's provider opened, or ReMa checked (`tool` is
 *  "check"); `arguments` holds the URL.
 */
"web_page" | 
/**
 *  ReMa's own search step before a job-search answer (`arguments`
 *  holds its status line).
 */
"retrieval" | 
/**
 *  A connector tool: mail, calendar or the application tracker
 *  (`server` names the connector). Changes always need approval, once
 *  per call.
 */
"connector";

/**  A page a web search found or opened. */
export type ActivitySource = {
	title: string,
	url: string,
};

/**  The outcome of adding several files at once. */
export type AddDocumentsResult = {
	added: ProfileDocument[],
	failed: RejectedFile[],
};

/**  An agent, built into ReMa or created by the user. */
export type Agent = {
	/**  `builtin:<slug>` or `custom:<number>`. */
	id: string,
	name: string,
	description: string,
	/**  The fixed instructions added to requests when the agent is selected. */
	instructions: string,
	/**  One of `AGENT_ICONS`. */
	icon: string,
	/**  Built-in agents cannot be edited or deleted; duplicate them instead. */
	builtin: boolean,
	/**  Custom agents: when last saved. */
	updatedAt: number | null,
};

/**  What the user enters for a custom agent. */
export type AgentInput = {
	name: string,
	description: string,
	instructions: string,
	icon: string,
};

/**  Agents were created, changed or deleted. */
export type AgentsChanged = null;

/**  Job data or research changed (ingestion, background details, research). */
export type AnalyticsChanged = null;

export type AnalyticsOverview = {
	summary: DatasetSummary,
	jobs: RankedJob[],
	/**  Rows beyond `jobs` that were not sent. */
	more: number,
	facets: Facets,
	status: PipelineStatus,
};

/**  The dashboard's working state, restored when it opens again. */
export type AnalyticsPreferences = {
	query: AnalyticsQuery,
	columns: JobColumn[],
	tab: DashboardTab,
	gap: SkillGapOptions,
	learning: LearningCriteria,
	/**  Read job pages in the background for descriptions and details. */
	readPages: boolean,
	/**  Let the default model extract requirements from descriptions. */
	useModel: boolean,
};

/**  The analytical dataset: scope → filters → ranking → optional top N. */
export type AnalyticsQuery = {
	scope: DataScope,
	filters?: FilterCondition[],
	ranking?: SortCriterion[],
	/**  Keep only the first N jobs of the ranking. */
	limit?: number | null,
};

/**  Response of the `get_app_status` command. */
export type AppStatus = {
	status: BackendStatus,
	app: string,
	version: string,
};

/**  ReMa's color theme. Light is the default. */
export type Appearance = "light" | "dark";

export type ApplicationDetail = {
	application: ApplicationRow,
	reference: string | null,
	timeline: TimelineEntry[],
	interviews: InterviewView[],
	correspondence: Correspondence[],
};

/**  One row of the Applications page: the application's current state. */
export type ApplicationRow = {
	id: number,
	company: string,
	role: string | null,
	status: ApplicationStatus,
	section: ApplicationSection,
	/**
	 *  The Status column, e.g. "Interview requested" (from the email that
	 *  set the status).
	 */
	statusLabel: string,
	/**  Received time of the latest email about this application. */
	lastUpdateAt: number,
	/**  The last column: latest update, requested action or rejection reason. */
	latestUpdate: string,
	nextAction: string | null,
	/**  Only when the rejection email states one. */
	rejectionReason: string | null,
	/**  For confirmed interviews: when the next one starts (epoch ms). */
	interviewAt: number | null,
	interviewTimezone: string | null,
	meetingUrl: string | null,
	/**  The confirmed interview overlaps existing events and was not added. */
	calendarConflict: boolean,
	/**  "google" / "microsoft": the mailbox of the latest email. */
	mailProvider: string | null,
};

/**
 *  The five sections of the Applications page, in page order. Every
 *  application is in exactly one, derived from its current status.
 */
export type ApplicationSection = "interviews_confirmed" | "applications_confirmed" | "needs_action" | "in_progress" | "rejected";

/**
 *  Where a job application stands. Stored as text and validated in Rust;
 *  new statuses (Offer, Assessment, Withdrawn, …) can be added as variants
 *  without a database migration.
 */
export type ApplicationStatus = 
/**  The company confirmed it received the application. */
"confirmed" | 
/**  Under review / waiting for news. */
"in_process" | 
/**  The user has to do something (reply, assessment, pick a slot). */
"needs_action" | 
/**  A confirmed interview is coming up. */
"upcoming_interview" | "rejected" | 
/**  The company made an offer. */
"offer";

/**  Applications or their timeline changed. */
export type ApplicationsChanged = null;

export type ApplicationsOverview = {
	/**  Every application, latest email first; each in one section. */
	applications: ApplicationRow[],
	tracking: TrackingStatus,
	/**  Emails the classifier was not sure about (no status was changed). */
	needsReview: Correspondence[],
};

export type ApprovalDecision = "allow" | 
/**  Allow this tool for the rest of the conversation (until ReMa quits). */
"allow_for_chat" | "deny";

