/**  Create or edit a task. Dates and times are local to `timezone`. */
export type TaskInput = {
	name: string,
	kind: TaskKind,
	prompt: string,
	/**  Give the model the user's Profile (prompt tasks). */
	useProfile: boolean,
	model: ModelRef,
	/**  IANA timezone, e.g. `Europe/Vienna`. */
	timezone: string,
	/**  `YYYY-MM-DD` */
	startDate: string,
	/**  `HH:MM` (24h) */
	startTime: string,
	schedule: Schedule,
	end: EndCondition,
};

/**  What a task does when it runs. */
export type TaskKind = 
/**  Sends the prompt to the model and keeps its answer. */
{ type: "prompt" } | 
/**
 *  "Job Mail & Interview Sync" (only as the built-in task): reads the
 *  connected mailboxes (Gmail, Outlook Mail) for job-application emails,
 *  keeps Applications up to date and adds confirmed interviews to the
 *  connected calendar (with conflict checks). The prompt adds the user's
 *  instructions.
 */
{ type: "job_applications"; 
/**
 *  Initial lookback: the first run reads the last N days (1–365);
 *  later runs read only new mail. A longer lookback backfills the
 *  newly included days once.
 */
lookbackDays: number; 
/**  Add confirmed interviews to the connected calendar. */
syncCalendar: boolean };

/**
 *  One run with everything it recorded. Its snapshot is the task as it was
 *  when the run was created; later edits never change it.
 */
export type TaskRun = {
	id: number,
	taskId: number,
	trigger: ExecutionTrigger,
	status: ExecutionStatus,
	scheduledFor: number | null,
	queuedAt: number,
	startedAt: number | null,
	finishedAt: number | null,
	/**  Start to finish, for finished runs. */
	durationMs: number | null,
	/**
	 *  Snapshot fields are `None` for runs recorded before snapshots were
	 *  kept (the prompt and model always were).
	 */
	taskName: string | null,
	kind: TaskKind | null,
	prompt: string,
	model: ModelRef,
	schedule: ScheduleSnapshot | null,
	useProfile: boolean | null,
	context: RunContext | null,
	/**  The answer (prompt tasks) or a plain-text summary (job tasks). */
	result: string | null,
	/**  Structured result of a Job Mail & Interview Sync run. */
	report: JobRunReport | null,
	/**  A safe, user-facing message. */
	error: string | null,
	errorCategory: RunErrorCategory | null,
	progress: RunProgressEvent[],
	outputs: RunOutput[],
};

/**  A run was created or changed (status, progress, outputs). */
export type TaskRunChanged = {
	taskId: number,
	runId: number,
};

/**  A page of a task's runs, newest first. */
export type TaskRunPage = {
	runs: TaskRunSummary[],
	/**  Older runs exist (ask again with the last id). */
	hasMore: boolean,
};

/**  One run in a task's history list. */
export type TaskRunSummary = {
	id: number,
	taskId: number,
	trigger: ExecutionTrigger,
	status: ExecutionStatus,
	/**  The occurrence a scheduled run belongs to. */
	scheduledFor: number | null,
	/**  When the run was created. */
	queuedAt: number,
	startedAt: number | null,
	finishedAt: number | null,
	errorCategory: RunErrorCategory | null,
};

/**  Lifecycle of a task as shown to the user. */
export type TaskStatus = 
/**  Enabled and has a next run. */
"active" | 
/**  Disabled by the user. */
"paused" | 
/**  No runs left (one-time task done, end date passed or run limit hit). */
"completed";

/**  Tasks or their runs changed (created, edited, ran, finished). */
export type TasksChanged = null;

/**  One entry of an application's audit timeline. */
export type TimelineEntry = {
	id: number,
	source: UpdateSource,
	change: string,
	status: ApplicationStatus,
	previousStatus: ApplicationStatus | null,
	category: EmailCategory | null,
	/**  0–1, for automatic updates. */
	confidence: number | null,
	summary: string | null,
	occurredAt: number,
	createdAt: number,
};

/**
 *  A tool call (or an unavailable server) while answering, shown with the
 *  message.
 */
export type ToolActivity = {
	/**  The model's call id (unique within the message). */
	id: string,
	serverId: number | null,
	server: string,
	tool: string,
	status: ToolStatus,
	/**  The arguments as compact JSON (shortened), shown before approval. */
	arguments: string,
	/**  What happened: a short result, an error or why it was denied. */
	detail: string | null,
	/**  The server marks the tool read-only (it ran without approval). */
	readOnly: boolean,
	kind?: ActivityKind,
	/**  Web activity: the pages found or opened. */
	sources?: ActivitySource[],
};

export type ToolStatus = 
/**  Waiting for the user to allow or deny the call. */
"awaiting_approval" | "running" | "completed" | "failed" | 
/**  The user denied it, or the answer was stopped first. */
"denied" | 
/**  A selected server could not be used for this answer. */
"unavailable";

/**
 *  Whether mail is being tracked: only the built-in scheduled task "Job
 *  Mail & Interview Sync" monitors mailboxes.
 */
export type TrackingStatus = {
	/**  The built-in task, if it was set up. */
	taskId: number | null,
	/**  Set up and turned on. */
	enabled: boolean,
	/**  A mail connector (Gmail, Outlook Mail) is connected. */
	mailConnected: boolean,
	lastRunAt: number | null,
	nextRunAt: number | null,
};

/**  Where a timeline entry came from. */
export type UpdateSource = "gmail" | "outlook" | "google_calendar" | "outlook_calendar" | 
/**  Changed by the user in ReMa. */
"user" | 
/**  Changed by the assistant with the user's approval. */
"assistant";

/**  `service: None` turns the service off (and removes its key). */
export type WebSearchInput = {
	service: ServiceKind | null,
	url: string | null,
	/**  `None` keeps the stored key. */
	key: string | null,
};

/**  The search service as Settings shows it. Never contains the key. */
export type WebSearchSettings = {
	service: ServiceKind | null,
	/**  SearXNG address. */
	url: string | null,
	hasKey: boolean,
};

/**  What a test search found. */
export type WebSearchTest = {
	results: number,
	titles: string[],
};

export type Weekday = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";

export type WorkMode = "remote" | "hybrid" | "onsite";

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

